/**
 * The Configuration form's pure half (ADR 0011 decisions 4 and 5): the fields a
 * form renders, the document a submission builds, what the copied schema says
 * about it, the diff against the document the form started from, the advice, and
 * the value the last answered call actually ran on.
 *
 * Nothing here touches Postgres, `FormData`, a clock or a request — the server
 * action is a thin dispatcher over these functions, and the whole of this file
 * is testable without either.
 *
 * The fields are **generated by walking the copied schema**, never written by
 * hand: the pipeline's document schema moves additively, and a hand-written
 * form would be a second schema that drifts from the bytes the contract pins.
 * The walk reads zod 4's `_zod.def` — the JSON-serialisable definition zod
 * documents for exactly this kind of traversal — and nothing else.
 */
import {
  runtimeConfigSchema,
  disclosureAdvice,
  type RuntimeConfig,
} from '@/contract/config/runtime-document';
import { FLAT_KEYS } from './flat-keys';
import { KEY_ALIASES, canonicalKey } from '@/dashboard';

/**
 * How one leaf is rendered. This console's own rendering vocabulary, not a
 * pipeline term: none of these words appears on a screen.
 */
export type ControlKind =
  | 'integer'
  | 'number'
  | 'boolean'
  | 'enum'
  | 'text'
  | 'textarea'
  | 'list'
  | 'record';

/** One leaf of the document, as the form renders it. */
export interface Field {
  /** The dotted document path, which is also the form control's name. */
  path: string;
  /** The top-level key the leaf lives under. */
  group: 'turn' | 'stt' | 'llm' | 'tts' | 'text';
  /** The provider branch the leaf belongs to, or null outside a branch. */
  vendor: string | null;
  /** From `FLAT_KEYS`; an object when the path has one key per vendor. */
  flatKey: string | Readonly<Record<string, string>>;
  kind: ControlKind;
  /** The values an `enum` offers; null for every other kind. */
  options: readonly string[] | null;
  /** The bounds the leaf's own schema carries, or null where it carries none. */
  min: number | null;
  max: number | null;
  minExclusive: boolean;
  maxExclusive: boolean;
}

/*
 * The shape of a zod node as this walk reads it. Deliberately narrow: only the
 * definition keys the traversal uses, so a zod change that moves one of them
 * fails `pnpm typecheck` here rather than yielding an empty form.
 */
interface ZodDef {
  type: string;
  shape?: Record<string, unknown>;
  innerType?: unknown;
  element?: unknown;
  options?: unknown[];
  discriminator?: string;
  values?: unknown[];
  checks?: unknown[];
}

function defOf(schema: unknown): ZodDef {
  const node = schema as { _zod?: { def?: ZodDef } };
  const def = node._zod?.def;
  if (def === undefined) throw new Error('not a zod schema: no _zod.def');
  return def;
}

/** `.optional()` and nothing else wraps a leaf in this document. */
function unwrapOptional(schema: unknown): unknown {
  const def = defOf(schema);
  return def.type === 'optional' ? def.innerType : schema;
}

/** The values a `z.enum()` offers, in declaration order. */
function enumOptions(schema: unknown): readonly string[] {
  return (schema as { options: readonly string[] }).options;
}

interface Bound {
  value: number;
  exclusive: boolean;
}

/**
 * The bounds a number leaf carries, read from its own `greater_than` /
 * `less_than` checks. The `minValue` / `maxValue` getters are not used: on an
 * integer leaf they also report the bounds of zod's `safeint` format, and
 * `Number.MAX_SAFE_INTEGER` is not a bound a form should show an operator.
 */
function boundsOf(schema: unknown): { min: Bound | null; max: Bound | null } {
  let min: Bound | null = null;
  let max: Bound | null = null;
  for (const check of defOf(schema).checks ?? []) {
    const def = defOf(check) as unknown as { check?: string; value?: number; inclusive?: boolean };
    if (typeof def.value !== 'number') continue;
    const bound = { value: def.value, exclusive: def.inclusive !== true };
    if (def.check === 'greater_than') min = bound;
    else if (def.check === 'less_than') max = bound;
  }
  return { min, max };
}

/** Whether a number leaf is an integer one (`z.int()`), by zod's own getter. */
function isInteger(schema: unknown): boolean {
  return (schema as { isInt?: boolean }).isInt === true;
}

const GROUPS = ['turn', 'stt', 'llm', 'tts', 'text'] as const;
type Group = (typeof GROUPS)[number];

function flatKeyFor(path: string): string | Readonly<Record<string, string>> {
  const entry = FLAT_KEYS[path];
  // Unreachable while `flat-keys.test.ts` holds the table total over the
  // schema's leaves; the path itself is the message if that test ever fails.
  if (entry === undefined) throw new Error(`no flat key for ${path}`);
  return entry;
}

function leafField(path: string, group: Group, vendor: string | null, schema: unknown): Field {
  const leaf = unwrapOptional(schema);
  const def = defOf(leaf);
  const base = {
    path,
    group,
    vendor,
    flatKey: flatKeyFor(path),
    options: null,
    min: null,
    max: null,
    minExclusive: false,
    maxExclusive: false,
  };
  switch (def.type) {
    case 'number': {
      const { min, max } = boundsOf(leaf);
      return {
        ...base,
        kind: isInteger(leaf) ? 'integer' : 'number',
        min: min?.value ?? null,
        max: max?.value ?? null,
        minExclusive: min?.exclusive ?? false,
        maxExclusive: max?.exclusive ?? false,
      };
    }
    case 'boolean':
      return { ...base, kind: 'boolean' };
    case 'enum':
      return { ...base, kind: 'enum', options: enumOptions(leaf) };
    case 'array':
      return { ...base, kind: 'list' };
    case 'record':
      return { ...base, kind: 'record' };
    case 'string':
      // The five `text.*` leaves are the spoken lines and the system prompt:
      // sentences and a prompt block, never a one-line value.
      return { ...base, kind: group === 'text' ? 'textarea' : 'text' };
    default:
      throw new Error(`unhandled leaf type '${def.type}' at ${path}`);
  }
}

/** Walk one `strictObject`, emitting its leaves in declaration order. */
function objectFields(
  schema: unknown,
  prefix: string,
  group: Group,
  vendor: string | null,
  out: Field[],
): void {
  const def = defOf(schema);
  for (const [key, child] of Object.entries(def.shape ?? {})) {
    const path = `${prefix}.${key}`;
    const inner = unwrapOptional(child);
    const innerDef = defOf(inner);
    // A nested group (`stt.params`, `llm.params`) rather than a leaf. The
    // Speechmatics and ElevenLabs branches carry a `superRefine` on their
    // params object, which is a check on the object, not another wrapper.
    if (innerDef.type === 'object') objectFields(inner, path, group, vendor, out);
    else out.push(leafField(path, group, vendor, inner));
  }
}

/**
 * Every leaf the document schema names, in declaration order, once per provider
 * branch that carries it. A path two branches share (`stt.params.language`,
 * `tts.params.speed`) yields one field per branch — the bounds differ between
 * them, which is the whole reason the branches exist.
 */
export function fieldsOf(): Field[] {
  const fields: Field[] = [];
  for (const group of GROUPS) {
    const child = defOf(runtimeConfigSchema).shape?.[group];
    const node = unwrapOptional(child);
    const def = defOf(node);
    if (def.type === 'union') {
      // A discriminated union: the discriminator is a field of its own (the
      // vendor a row names, ADR 0028 D1), then one pass per branch.
      const branches = def.options ?? [];
      const discriminator = def.discriminator ?? 'provider';
      const path = `${group}.${discriminator}`;
      const providers = branches.map(
        (branch) => defOf(defOf(branch).shape?.[discriminator]).values?.[0] as string,
      );
      fields.push({
        path,
        group,
        vendor: null,
        flatKey: flatKeyFor(path),
        kind: 'enum',
        options: providers,
        min: null,
        max: null,
        minExclusive: false,
        maxExclusive: false,
      });
      branches.forEach((branch, index) => {
        const vendor = providers[index] ?? null;
        for (const [key, leaf] of Object.entries(defOf(branch).shape ?? {})) {
          if (key === discriminator) continue;
          const leafPath = `${group}.${key}`;
          const inner = unwrapOptional(leaf);
          if (defOf(inner).type === 'object') objectFields(inner, leafPath, group, vendor, fields);
          else fields.push(leafField(leafPath, group, vendor, inner));
        }
      });
      continue;
    }
    objectFields(node, group, group, null, fields);
  }
  return fields;
}

/** One row of the form: a field, and the bounds a merged one cannot carry. */
export interface BranchMerge {
  field: Field;
  /** `cartesia 0.6–1.5 · elevenlabs 0.7–1.2`, or null where no branch bounds it. */
  vendorBounds: string | null;
}

/** One field's own bounds as a hint reads them, or null when it has none. */
function boundsText(field: Field): string | null {
  const { min, max } = field;
  if (min !== null && max !== null) {
    return `${field.minExclusive ? 'above ' : ''}${String(min)}–${field.maxExclusive ? 'below ' : ''}${String(max)}`;
  }
  if (min !== null) return `${field.minExclusive ? 'greater than' : 'at least'} ${String(min)}`;
  if (max !== null) return `${field.maxExclusive ? 'less than' : 'at most'} ${String(max)}`;
  return null;
}

/**
 * The branches of one path as a single control, for the no-script path where
 * every branch renders at once: the union of every branch's options in
 * declaration order, deduplicated, and NO bound at all — one vendor's `min` or
 * `max` on the control would refuse a value another vendor accepts, and would
 * mark a stored value of a third vendor as one this build does not offer. The
 * bounds travel in the hint instead, per vendor, and the copied schema refuses
 * the wrong value at review, which is where the operator reads it.
 */
export function mergeBranches(branches: readonly Field[]): BranchMerge {
  const first = branches[0];
  if (first === undefined) throw new Error('a path with no field');
  if (branches.length === 1) return { field: first, vendorBounds: null };

  const options: string[] = [];
  for (const branch of branches) {
    for (const option of branch.options ?? []) {
      if (!options.includes(option)) options.push(option);
    }
  }
  const bounds = branches
    .map((branch) => {
      const text = boundsText(branch);
      return branch.vendor === null || text === null ? null : `${branch.vendor} ${text}`;
    })
    .filter((line): line is string => line !== null);

  return {
    field: {
      ...first,
      vendor: null,
      options: options.length === 0 ? null : options,
      min: null,
      max: null,
      minExclusive: false,
      maxExclusive: false,
    },
    vendorBounds: bounds.length === 0 ? null : bounds.join(' · '),
  };
}

/** Every leaf path, in declaration order, each once however many branches carry it. */
export function leafPaths(): string[] {
  return [...new Set(fieldsOf().map((field) => field.path))];
}

/** The value at a dotted path, or `undefined` when any step of it is absent. */
function valueAt(document: unknown, path: string): unknown {
  let node: unknown = document;
  for (const segment of path.split('.')) {
    if (typeof node !== 'object' || node === null || Array.isArray(node)) return undefined;
    if (!Object.hasOwn(node, segment)) return undefined;
    node = (node as Record<string, unknown>)[segment];
  }
  return node;
}

/**
 * The form's starting state: the string every control shows, and the paths whose
 * `set:` checkbox starts ticked. Keyed on the stored value's own type rather
 * than on the field's kind, because a stored document may carry a leaf of
 * another branch — this fills the control, the schema judges it.
 */
export function formFromDocument(doc: unknown): { values: Record<string, string>; set: string[] } {
  const values: Record<string, string> = {};
  const set: string[] = [];
  for (const path of leafPaths()) {
    const value = valueAt(doc, path);
    if (value === undefined) continue;
    set.push(path);
    if (typeof value === 'string') values[path] = value;
    else if (typeof value === 'number' || typeof value === 'boolean') values[path] = String(value);
    else if (Array.isArray(value)) values[path] = value.map(String).join('\n');
    else values[path] = JSON.stringify(value, null, 2);
  }
  return { values, set };
}

/**
 * The document one submission means. Only a leaf whose `set:<path>` entry is
 * present is in it — an absent leaf is the boot value (contract §3.4), which is
 * a different fact from an empty one.
 *
 * Coercion never repairs: a number that does not parse and a record whose JSON
 * does not parse stay the raw string, so `parseDocument` reports the issue on
 * that leaf's own path instead of the form silently sending something else. A
 * leaf belonging to another vendor's branch is kept for the same reason: the
 * schema is `strictObject` at every level precisely so that it becomes an
 * `unrecognized_keys` issue the operator reads, never a dropped edit.
 */
export function documentFromForm(entries: Iterable<[string, string]>): Record<string, unknown> {
  const form = new Map(entries);
  const byPath = new Map<string, Field[]>();
  for (const field of fieldsOf()) {
    const existing = byPath.get(field.path);
    if (existing === undefined) byPath.set(field.path, [field]);
    else existing.push(field);
  }
  const document: Record<string, unknown> = {};
  for (const [path, fields] of byPath) {
    if (!form.has(`set:${path}`)) continue;
    const raw = form.get(path) ?? '';
    const kind = fields[0]?.kind ?? 'text';
    write(document, path, coerce(raw, kind));
  }
  return document;
}

function coerce(raw: string, kind: ControlKind): unknown {
  switch (kind) {
    case 'integer':
    case 'number': {
      const value = Number(raw.trim());
      // The raw string when it is not a number — including the empty string,
      // which `Number` reads as 0.
      return raw.trim() === '' || Number.isNaN(value) ? raw : value;
    }
    case 'boolean':
      return raw === 'true' ? true : raw === 'false' ? false : raw;
    case 'list':
      return raw
        .split('\n')
        .map((line) => line.trim())
        .filter((line) => line !== '');
    case 'record':
      try {
        return JSON.parse(raw) as unknown;
      } catch {
        return raw;
      }
    case 'enum':
    case 'text':
    case 'textarea':
      return raw;
  }
}

function write(document: Record<string, unknown>, path: string, value: unknown): void {
  const segments = path.split('.');
  const leaf = segments.pop();
  if (leaf === undefined) return;
  let node = document;
  for (const segment of segments) {
    const existing = node[segment];
    if (typeof existing !== 'object' || existing === null || Array.isArray(existing)) {
      node[segment] = {};
    }
    node = node[segment] as Record<string, unknown>;
  }
  node[leaf] = value;
}

/** One refusal, on the leaf path it belongs to. */
export interface DocumentIssue {
  path: string;
  message: string;
}

/**
 * The copied schema's verdict — the same one the pipeline runs on the row, so an
 * edit the call would refuse is refused in the form instead. A cross-field
 * `superRefine` reports on its own leaf path, so it maps to a field like any
 * other issue.
 */
export function parseDocument(
  doc: unknown,
): { ok: true; document: RuntimeConfig } | { ok: false; issues: DocumentIssue[] } {
  const result = runtimeConfigSchema.safeParse(doc);
  if (result.success) return { ok: true, document: result.data };
  return {
    ok: false,
    issues: result.error.issues.map((issue) => ({
      path: issue.path.join('.'),
      message: issue.message,
    })),
  };
}

export interface DiffEntry {
  path: string;
  change: 'added' | 'removed' | 'changed';
  from: unknown;
  to: unknown;
}

/**
 * A JSON value as one canonical string: object keys sorted at every level,
 * array order kept, because order is meaning in `llm.params.stop` and the term
 * lists. The same rule `src/dashboard.ts` groups snapshots by, written here
 * because that copy is private to the dashboard — with one difference it needs:
 * an absent leaf reads as `undefined` rather than as `null`, because absent
 * means "the boot value applies" (§3.4) and a stored null does not.
 */
function canonicalJson(value: unknown): string {
  if (value === undefined) return 'undefined';
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  const object = value as Record<string, unknown>;
  const fields = Object.keys(object)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(object[key])}`);
  return `{${fields.join(',')}}`;
}

/**
 * Every leaf that differs between the document the form started from and the
 * one it proposes, in schema declaration order. A key the schema does not name
 * — a row written by hand, or a contract that has moved (trap 6) — is never
 * dropped from the diff: it is appended after the known leaves, sorted, so it
 * is visible rather than invisible.
 */
export function diffDocuments(from: unknown, to: unknown): DiffEntry[] {
  const known = leafPaths();
  const paths = [...known, ...unknownPaths(from, to, new Set(known))];
  const entries: DiffEntry[] = [];
  for (const path of paths) {
    const before = valueAt(from, path);
    const after = valueAt(to, path);
    if (canonicalJson(before) === canonicalJson(after)) continue;
    const change =
      before === undefined ? 'added' : after === undefined ? 'removed' : ('changed' as const);
    entries.push({ path, change, from: before, to: after });
  }
  return entries;
}

/** The dotted paths either document carries that the schema does not name. */
function unknownPaths(from: unknown, to: unknown, known: Set<string>): string[] {
  const found = new Set<string>();
  const walk = (node: unknown, prefix: string): void => {
    if (prefix !== '' && known.has(prefix)) return;
    if (typeof node === 'object' && node !== null && !Array.isArray(node)) {
      const object = node as Record<string, unknown>;
      for (const key of Object.keys(object)) {
        walk(object[key], prefix === '' ? key : `${prefix}.${key}`);
      }
      // An object is never a leaf, not even an empty one: `{turn:{}}` and `{}`
      // carry the same leaves, so the diff between them is empty rather than a
      // `removed turn` the operator cannot act on.
      return;
    }
    if (prefix !== '') found.add(prefix);
  };
  walk(from, '');
  walk(to, '');
  return [...found].sort();
}

/**
 * What the operator should know before saving, never a refusal (ADR 0011
 * decision 5; the disclosure rule is advice by pipeline ADR 0021 D5 and the
 * reasoning rule is a runbook §10 rule the schema deliberately does not
 * enforce).
 */
export function adviceFor(from: unknown, to: RuntimeConfig): string[] {
  const advice: string[] = [];
  const greeting = to.text?.greeting;
  if (greeting !== undefined) advice.push(...disclosureAdvice(greeting));
  const model = to.llm?.model;
  if (
    model !== undefined &&
    model !== valueAt(from, 'llm.model') &&
    to.llm?.params?.reasoning === undefined
  ) {
    advice.push(
      'llm.model changed but llm.params.reasoning is not set in this row — a value the model rejects is HTTP 400 on every turn (runbook §10).',
    );
  }
  return advice;
}

/**
 * What the last answered call actually ran on for this leaf: the snapshot's own
 * flat key, or `undefined` when the snapshot does not carry it — which is the
 * usual answer for another vendor's parameter, and never a default (§3.4).
 *
 * A per-vendor path is resolved by the snapshot's OWN `STT_PROVIDER` /
 * `TTS_PROVIDER`, `tts.*` by the TTS one and everything else by the STT one —
 * the rule `flatKeyOf` in `../Fonnus/app/src/config/runtime.ts` applies to a
 * document, applied here to the record that document produced. Both spellings of
 * the three Deepgram keys renamed on 2026-09-17 resolve to one value
 * (`KEY_ALIASES`, ADR 0009).
 */
export function ranOn(snapshot: Record<string, unknown> | null, field: Field): unknown {
  if (snapshot === null) return undefined;
  let key: string | undefined;
  if (typeof field.flatKey === 'string') {
    key = field.flatKey;
  } else {
    const provider = lookup(snapshot, field.path.startsWith('tts.') ? 'TTS_PROVIDER' : 'STT_PROVIDER');
    key = typeof provider === 'string' ? field.flatKey[provider] : undefined;
  }
  return key === undefined ? undefined : lookup(snapshot, key);
}

/** One snapshot key's value, under either spelling of a renamed key; own keys only. */
function lookup(snapshot: Record<string, unknown>, key: string): unknown {
  const canonical = canonicalKey(key);
  if (Object.hasOwn(snapshot, canonical)) return snapshot[canonical];
  const old = KEY_ALIASES[canonical];
  if (old !== undefined && Object.hasOwn(snapshot, old)) return snapshot[old];
  return undefined;
}
